export function createLimiter(opts: { perMinute: number }): { take(key: string, now: number): boolean } {
  const buckets = new Map<string, { tokens: number; at: number }>();
  const cap = opts.perMinute;
  return {
    take(key, now) {
      const b = buckets.get(key) ?? { tokens: cap, at: now };
      b.tokens = Math.min(cap, b.tokens + Math.max(0, now - b.at) * (cap / 60000));
      b.at = now;
      const ok = b.tokens >= 1;
      if (ok) b.tokens -= 1;
      buckets.set(key, b);
      return ok;
    },
  };
