import { existsSync } from "node:fs";
import { join } from "node:path";
import { createLimiter, parseRepoUrl } from "../../../lib/try";

const limiter = createLimiter({ perMinute: 5 });

export async function POST(req: Request): Promise<Response> {
  const ip = req.headers.get("x-forwarded-for")?.split(",")[0]?.trim() || "unknown";
  if (!limiter.take(ip, Date.now())) return Response.json({ error: "rate limited" }, { status: 429 });
  let body: unknown;
  try {
    body = await req.json();
  } catch {
    return Response.json({ error: "invalid json" }, { status: 400 });
  }
  const repo = (body as { repo?: unknown } | null)?.repo;
  const parsed = typeof repo === "string" ? parseRepoUrl(repo) : null;
  if (!parsed) return Response.json({ error: "invalid repo" }, { status: 400 });
  const rel = `data/r/${parsed.owner}/${parsed.repo}/review.json`;
  if (existsSync(join(process.cwd(), "public", rel))) {
    return Response.json({ cached: true, path: `/${rel}` });
  }
  return Response.json({ queued: true }, { status: 202 });
}
EOF
