import { describe, expect, test } from "bun:test";
import { createLimiter, parseRepoUrl } from "../web/lib/try.ts";

describe("parseRepoUrl", () => {
  test("accepts valid forms", () => {
    const want = { owner: "a-b", repo: "r.x_y" };
    for (const i of ["https://github.com/a-b/r.x_y", "https://github.com/a-b/r.x_y.git", "https://github.com/a-b/r.x_y/", "a-b/r.x_y"])
      expect(parseRepoUrl(i)).toEqual(want);
  });
  test("rejects invalid", () => {
    for (const i of ["https://gitlab.com/a/b", "http://github.com/a/b", "https://github.com/a/b/tree/x", "a", "a/b/c", "-a/b", "a-/b", "a--b/c", "a/..", "a/b c", "a/b?x", "", "https://github.com/evil.com/../b", "https://notgithub.com/a/b"])
      expect(parseRepoUrl(i)).toBeNull();
  });
});

describe("createLimiter", () => {
  test("bucket per key with refill", () => {
    const l = createLimiter({ perMinute: 2 });
    expect([l.take("a", 0), l.take("a", 0), l.take("a", 0)]).toEqual([true, true, false]);
    expect(l.take("b", 0)).toBe(true);
    expect(l.take("a", 30000)).toBe(true);
    expect(l.take("a", 30000)).toBe(false);
  });
});
EOF
